    codeSnippet: '// Fair-share QueueSort plugin:\nfunc (f *FairShareSort) Less(pInfo1, pInfo2 *framework.QueuedPodInfo) bool {\n    team1 := getTeam(pInfo1.Pod)\n    team2 := getTeam(pInfo2.Pod)\n\n    // Get current resource usage vs fair share\n    usage1 := f.getTeamUsageRatio(team1) // current / entitled\n    usage2 := f.getTeamUsageRatio(team2)\n\n    // Teams under their fair share get priority\n    if usage1 != usage2 {\n        return usage1 < usage2 // Under-share team goes first\n    }\n\n    // Within same share ratio, use standard priority\n    return pInfo1.Pod.Spec.Priority != nil &&\n        pInfo2.Pod.Spec.Priority != nil &&\n        *pInfo1.Pod.Spec.Priority > *pInfo2.Pod.Spec.Priority\n}\n\n// Example:\n// Team A: entitled to 40% of cluster, using 60% -> ratio 1.5\n// Team B: entitled to 30% of cluster, using 20% -> ratio 0.67\n// Team C: entitled to 30% of cluster, using 30% -> ratio 1.0\n//\n// Scheduling order: Team B (0.67) > Team C (1.0) > Team A (1.5)',
