    codeSnippet: '// Zero-downtime deployment strategy:\n//\n// Service dependency graph: A -> B -> C (A depends on B, B depends on C)\n//\n// Step 1: Deploy C first (no dependencies)\n// - PDB: maxUnavailable: 1\n// - Strategy: maxSurge: 1, maxUnavailable: 0\n// - Readiness probe: /health (checks C\'s own health)\n//\n// Step 2: Deploy B after C is fully rolled out\n// - PDB: maxUnavailable: 1\n// - Strategy: maxSurge: 1, maxUnavailable: 0\n// - Readiness probe: /health (checks B + C connectivity)\n// - ReadinessGate: service-b-dependency-check\n//\n// Step 3: Deploy A after B is fully rolled out\n// - PDB: maxUnavailable: 1\n// - Strategy: maxSurge: 1, maxUnavailable: 0\n// - Readiness probe: /health (checks A + B connectivity)\n//\n// Coordination controller:\nfunc (r *DeploymentOrchestratorReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {\n    graph := r.buildDependencyGraph(ctx)\n\n    // Deploy in topological order\n    for _, tier := range graph.TopologicalSort() {\n        for _, svc := range tier {\n            if err := r.rolloutService(ctx, svc); err != nil {\n                return ctrl.Result{RequeueAfter: 30 * time.Second}, nil\n            }\n        }\n        // Wait for tier to be fully healthy before proceeding\n        if !r.isTierHealthy(ctx, tier) {\n            return ctrl.Result{RequeueAfter: 10 * time.Second}, nil\n        }\n    }\n    return ctrl.Result{}, nil\n}',
